const input = $input.first().json ?? {};
const isWebhook = !!input.body || !!input.headers || !!input.webhookUrl;
const body = (input.body && typeof input.body === 'object') ? input.body : input;
const pick = (...values) => { for (const v of values) { if (v !== undefined && v !== null && String(v).trim() !== '') return v; } return null; };
const triggerType = isWebhook ? 'webhook' : 'chat';
const channel = String(pick(body.channel, triggerType === 'webhook' ? 'website' : 'n8n_chat')).trim().toLowerCase();
const rawSessionId = String(pick(body.session_id, body.sessionId, input.sessionId, input.session_id, `session-${Date.now()}-${Math.random().toString(36).slice(2,8)}`));
const sessionId = rawSessionId.trim();
const sessionKey = `${channel}:${sessionId}`;
const message = String(pick(body.message, body.chatInput, body.text, input.chatInput, input.message, input.text, '') ?? '').trim();
const externalUserId = sessionKey; // Contact details never authorize private history.
const requestId = String(pick(body.request_id, body.requestId, body.message_id, body.messageId, `${sessionId}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`));
return [{json:{entrypoint:'chat',trigger_type:triggerType,channel,session_id:sessionId,session_key:sessionKey,external_user_id:externalUserId,request_id:requestId,message,name:pick(body.visitor_name,body.name,body.customer_name,body.customerName,body.first_name,body.firstName,body.customer_details?.name,body.customer_details?.first_name,body.customer?.name,body.customer?.first_name),phone:pick(body.phone,body.mobile,body.customer_details?.phone),email:pick(body.visitor_email,body.email,body.customer_details?.email),city:pick(body.city,body.location,body.town,body.customer_details?.city),received_internal_token:'',input_valid:message.length>0}}];

const n = $('Normalize Input').first().json;
const reply = 'Please send a message so I can help with Lanka Electro Mart products, prices, stock, comparisons, branches, or quotations.';
return [{json:{success:false,trigger_type:n.trigger_type,session_id:n.session_id,request_id:n.request_id,intent:'validation',duplicate:false,reply,output:reply}}];

const n = $('Normalize Input').first().json;
let raw = $input.first().json ?? {};
for (let i=0;i<4;i++) {
  if (typeof raw==='string') { try { raw=JSON.parse(raw); continue; } catch { break; } }
  if (Array.isArray(raw)) { raw=raw[0]??{}; continue; }
  if (raw?.body!==undefined) { raw=raw.body; continue; }
  break;
}

const ok = raw && raw.ok === true;
const history = Array.isArray(raw.history) ? raw.history : [];

const err =
  raw?.message ||
  raw?.error?.message ||
  (typeof raw?.error === 'string' ? raw.error : null) ||
  raw?.details ||
  raw?.hint ||
  (ok ? null : 'Supabase prepare-chat request failed');

return [{
  json: {
    ...n,
    backend_prepare_ok: ok,
    backend_prepare_error: err,
    backend_http_code: raw?.statusCode ?? raw?.status ?? null,
    backend_error_code: raw?.code ?? null,
    duplicate: ok && raw.duplicate === true,
    in_progress: ok && raw.in_progress === true,
    previous_response: raw.previous_response ?? null,
    customer_id: raw.customer_id ?? null,
    history,
    name:raw.customer?.name ?? n.name,
    phone:raw.customer?.phone ?? n.phone,
    email:raw.customer?.email ?? n.email,
    city:raw.customer?.city ?? n.city
  }
}];

const s=$input.first().json;
const inProgress=s.in_progress===true && !s.previous_response;
const singlish=/\b(mage|mata|ekak|one|denna|kiyada|gannam)\b/i.test(s.message??'');
const reply=s.previous_response || (singlish?'Oyage kalin illima thawama process wenawa. Poddak indala balanna.':'Your earlier request is still processing. Please check again shortly.');
return [{json:{success:!inProgress,trigger_type:s.trigger_type,session_id:s.session_id,request_id:s.request_id,intent:inProgress?'request_in_progress':'duplicate',duplicate:true,in_progress:inProgress,reply,output:reply}}];

