={{ (() => {
  const q = String($fromAI(
    'search_query',
    'REQUIRED concise search such as smartphone camera battery. Never null.',
    'string',
    'products'
  ) ?? 'products').trim() || 'products';

  const minRaw = String($fromAI(
    'min_price_lkr',
    'Minimum budget LKR as digits in a STRING. If absent use exactly 0. Never null.',
    'string',
    '0'
  ) ?? '0');

  const maxRaw = String($fromAI(
    'max_price_lkr',
    'Maximum budget LKR as digits in a STRING. If absent use exactly 0. Never null.',
    'string',
    '0'
  ) ?? '0');

  const locRaw = String($fromAI(
    'location',
    'Customer city or requested branch. If absent use exactly NONE. Never null.',
    'string',
    'NONE'
  ) ?? 'NONE').trim();

  const toOptionalNumber = (v) => {
    const cleaned = String(v).replace(/[^0-9.]/g, '');
    const n = Number(cleaned);
    return Number.isFinite(n) && n > 0 ? n : null;
  };

  const location = /^(none|any|null|n\/a|-)?$/i.test(locRaw) ? '' : locRaw;

  return JSON.stringify({
    p_action: 'search_products',
    p_payload: {
      query: q,
      category: '',
      brand: '',
      min_price: toOptionalNumber(minRaw),
      max_price: toOptionalNumber(maxRaw),
      location,
      branch: '',
      in_stock: true,
      limit: 6
    }
  });
})() }}

