const s=$('Parse Chat State').first().json;
const a=$input.first().json??{};
const value=a.output??a.text??a.reply??'';
let reply=typeof value==='string'?value.trim():'';
const agentFailed=!!a.error || !reply;
const singlish=/\b(mata|mage|meka|ekak|on[eai]|kiyada|gana|denna|puluwan|adu|balanna|thawa|kohomada|gannam|oyage)\b/i.test(s.message??'');
const fallback=singlish?'Me illima danma sampurna karanna bari una. Nawatha try karanna puluwanda?':'I could not complete that request just now. Please try again.';
if(!reply) reply=fallback;
const receipts=[];
function collect(v,depth=0){
 if(depth>12||v==null)return;
 if(typeof v==='string'){try{collect(JSON.parse(v),depth+1)}catch{};return}
 if(Array.isArray(v)){for(const x of v)collect(x,depth+1);return}
 if(typeof v!=='object')return;
 if(v.success===true)receipts.push(v);
 else if(v.success!==false)for(const x of Object.values(v))collect(x,depth+1);
}
for(const step of (a.intermediateSteps??[]))collect(step.observation);
const allowed=new Set();const knownSkus=new Set();
function priceValues(v){
 if(!v||typeof v!=='object')return;
 for(const [k,x] of Object.entries(v)){
  if(k==='sku'&&typeof x==='string')knownSkus.add(x.toUpperCase());
  if(x!==null&&/price|subtotal|total_amount|merchandise_total|discount_amount|discount_lkr|threshold|fee/i.test(k)&&typeof x==='number')allowed.add(x.toFixed(2));
  if(typeof x==='object')priceValues(x);
 }
}
for(const r of receipts)priceValues(r);
let unsupported=false;
for(const m of reply.matchAll(/(?:LKR|Rs\.?|රු\.?)\s*([0-9][0-9,]*(?:\.[0-9]{1,2})?)/gi)){
 const num=Number(m[1].replace(/,/g,''));
 const context=reply.slice(Math.max(0,m.index-65),m.index).toLowerCase();
 // A customer budget may be reflected explicitly; it cannot authorize a product price.
 const budgetMention=/budget|max(?:imum)?\s+(?:spend|amount)|spend\s+limit/.test(context);
 const userNumbers=String(s.message??'').match(/[0-9][0-9,]*(?:\.[0-9]+)?/g)??[];
 const fromCustomer=userNumbers.some(n=>Number(n.replace(/,/g,''))===num);
 if(!allowed.has(num.toFixed(2))&&!(budgetMention&&fromCustomer))unsupported=true;
}
for(const m of reply.matchAll(/LEM-(?:SAMPLE|DEMO)-[A-Z0-9-]+/gi))if(!knownSkus.has(m[0].toUpperCase()))unsupported=true;
if(unsupported){
 const basket=[...receipts].reverse().find(r=>typeof r.total_amount==='number'&&r.items?.length);
 const search=[...receipts].reverse().find(r=>r.action==='search_products'&&r.results?.length);
 const money=n=>Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
 if(basket){
  reply=singlish?`Demo basket eke merchandise total eka LKR ${money(basket.total_amount)}. Delivery saha installation charges me ganata athulath wela naha. Me items walata collection quotation ekak oneda?`:`The verified demo merchandise total is LKR ${money(basket.total_amount)}. Delivery and installation charges are pending. Would you like a demo collection quote for these items?`;
 }else if(search){
  const p=search.results[0];
  reply=singlish?`Demo catalogue anuwa ${p.name}, SKU ${p.sku}, ${p.variant??''}: LKR ${money(p.current_price_lkr)}. Me demo merchandise price ekata delivery charges athulath naha. Me model ekata demo quotation ekak oneda?`:`The demo catalogue lists ${p.name}, SKU ${p.sku}, ${p.variant??''}, at LKR ${money(p.current_price_lkr)} for one unit. Delivery charges are pending. Would you like a demo quote for this model?`;
 }else{
  reply=singlish?'Me product eke current mila thahawuru karanna bari una. Oyage budget ekata galapena model ekak hoyanna product details verify karanna one.':'I could not verify a current price for that product. Current catalogue details are needed before I can give a priced recommendation.';
 }
}
reply=reply.replace(/\*/g,'').replace(/^\s*#{1,6}\s+/gm,'').replace(/```[^\n]*\n?/g,'').trim();
return [{json:{...s,reply,intent:unsupported?'price_verification_guard':'ai_agent',agent_error:a.error??(agentFailed?'AGENT_REPLY_MISSING':null),price_guard_triggered:unsupported}}];

const s=$('Build Reply').first().json;
let saved=$input.first().json??{};
for(let i=0;i<4;i++) {
 if(typeof saved==='string'){try{saved=JSON.parse(saved);continue}catch{break}}
 if(Array.isArray(saved)){saved=saved[0]??{};continue}
 if(saved?.body!==undefined){saved=saved.body;continue}
 break;
}
return [{json:{success:!s.agent_error,trigger_type:s.trigger_type,session_id:s.session_id,request_id:s.request_id,intent:s.intent,duplicate:false,reply:s.reply,output:s.reply,memory_saved:saved?.ok===true}}];

