const SUPABASE_URL = 'https://ihluonyznulznicffhqe.supabase.co';
const input=$input.first().json??{};
const url=SUPABASE_URL.trim().replace(/\/$/,'');
const valid=/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(url);
return [{json:{...input,supabase_url:url,deployment_mode:'demo',business_id:'lanka_electro_mart',config_valid:valid,config_error:valid?null:'Store connection is not configured.'}}];

